window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-878e2f819c1f7a05"]={"versions": [{"id": "FIG-878e2f819c1f7a05", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Objektdiagramm (M2/M1-Instanzdarstellung) zur Veranschaulichung der Modellstruktur und Änderungsverfolgung von AUTOSAR-Modellen im Rahmen des AUTOSAR-Tool-Interoperabilitätskonzepts. Es zeigt die Objekthierarchie und Referenzen eines M1-Modellausschnitts nach einer Modifikation.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellt sind folgende UML-Objektinstanzen mit ihren Attributen und Assoziationen:</p>\n<ul class=\"fig-list\">\n<li><code>:ARPackage</code> mit Attribut <code>shortName = OEM</code>.</li>\n<li><code>:SenderReceiverInterface</code> mit Attributen <code>isService = false</code>, <code>shortName = interface</code>, über Kompositionsrolle <code>+element</code> in <code>:ARPackage</code> enthalten.</li>\n<li><code>:VariableDataPrototype</code> mit Attribut <code>shortName = velocity</code>, über Kompositionsrolle <code>+dataElement</code> in <code>:SenderReceiverInterface</code> enthalten.</li>\n<li><code>:ApplicationPrimitiveDataType</code> (hervorgehoben in Grün) mit Attribut <code>shortName = velocityType</code>, über Kompositionsrolle <code>+element</code> in <code>:ARPackage</code> enthalten; <code>:VariableDataPrototype</code> referenziert dieses Datentyptyp-Objekt über eine gerichtete Assoziation <code>+type</code>.</li>\n<li><code>:NumericalValueSpecification</code> (hervorgehoben in Grün) mit den Werten <code>VALUE = 20000</code> und <code>value = 20000</code>, über Kompositionsrolle <code>+invalidValue</code> an <code>:ApplicationPrimitiveDataType</code> angebunden.</li>\n<li><code>:DisplayFormatString</code> mit Attribut <code>value = %f6.2</code>, über Kompositionsrolle <code>+displayFormat</code> an <code>:ApplicationPrimitiveDataType</code> angebunden.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Objektdiagramm ohne dynamische Ablauf- oder Interaktionssequenzen. Die farbliche Hervorhebung (grün) visualisiert die Propagation einer Modelländerung: Eine Modifikation am Kindelement <code>:NumericalValueSpecification</code> (invalidValue) propagiert zum übergeordneten identifizierbaren Element <code>:ApplicationPrimitiveDataType</code>.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm dient als Referenzbeispiel für AUTOSAR-Autorentools zur Erkennung und Propagierung von Modelländerungen. Werkzeuge müssen erkennen, dass eine Modifikation an einer untergeordneten <code>ValueSpecification</code> (hier <code>invalidValue</code>) eine Änderung des enthaltenden <code>ApplicationPrimitiveDataType</code> darstellt, während referenzierende Elemente (<code>VariableDataPrototype</code>) oder benachbarte Instanzen unverändert bleiben.</p>"}, {"id": "FIG-228d62beee91ce7d", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Objektdiagramm (M2/M1-Instanzdarstellung) zur Veranschaulichung der Modellstruktur und Änderungsverfolgung von AUTOSAR-Modellen im Rahmen des AUTOSAR-Tool-Interoperabilitätskonzepts. Es zeigt die Objekthierarchie und Referenzen eines M1-Modellausschnitts nach einer Modifikation.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellt sind folgende UML-Objektinstanzen mit ihren Attributen und Assoziationen:</p>\n<ul class=\"fig-list\">\n<li><code>:ARPackage</code> mit Attribut <code>shortName = OEM</code>.</li>\n<li><code>:SenderReceiverInterface</code> mit Attributen <code>isService = false</code>, <code>shortName = interface</code>, über Kompositionsrolle <code>+element</code> in <code>:ARPackage</code> enthalten.</li>\n<li><code>:VariableDataPrototype</code> mit Attribut <code>shortName = velocity</code>, über Kompositionsrolle <code>+dataElement</code> in <code>:SenderReceiverInterface</code> enthalten.</li>\n<li><code>:ApplicationPrimitiveDataType</code> (hervorgehoben in Grün) mit Attribut <code>shortName = velocityType</code>, über Kompositionsrolle <code>+element</code> in <code>:ARPackage</code> enthalten; <code>:VariableDataPrototype</code> referenziert dieses Datentyptyp-Objekt über eine gerichtete Assoziation <code>+type</code>.</li>\n<li><code>:NumericalValueSpecification</code> (hervorgehoben in Grün) mit den Werten <code>VALUE = 20000</code> und <code>value = 20000</code>, über Kompositionsrolle <code>+invalidValue</code> an <code>:ApplicationPrimitiveDataType</code> angebunden.</li>\n<li><code>:DisplayFormatString</code> mit Attribut <code>value = %f6.2</code>, über Kompositionsrolle <code>+displayFormat</code> an <code>:ApplicationPrimitiveDataType</code> angebunden.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Objektdiagramm ohne dynamische Ablauf- oder Interaktionssequenzen. Die farbliche Hervorhebung (grün) visualisiert die Propagation einer Modelländerung: Eine Modifikation am Kindelement <code>:NumericalValueSpecification</code> (invalidValue) propagiert zum übergeordneten identifizierbaren Element <code>:ApplicationPrimitiveDataType</code>.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm dient als Referenzbeispiel für AUTOSAR-Autorentools zur Erkennung und Propagierung von Modelländerungen. Werkzeuge müssen erkennen, dass eine Modifikation an einer untergeordneten <code>ValueSpecification</code> (hier <code>invalidValue</code>) eine Änderung des enthaltenden <code>ApplicationPrimitiveDataType</code> darstellt, während referenzierende Elemente (<code>VariableDataPrototype</code>) oder benachbarte Instanzen unverändert bleiben.</p>"}], "trans": [{"from": "FIG-878e2f819c1f7a05", "to": "FIG-228d62beee91ce7d", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
